// th18_s4_w07  Stage 4 MainSub04 S:947-1002 + Phantom01 S:1057-1156
// 源/卡对应关系写在相关段旁；源行号均指 st04.ecl.txt。

const TIME_LIMIT: int = 1700;      // 含 120 帧外壳缓冲；源无超时，见 report.md
const TH18_RICE: int = 480;        // type 8, color 6
const TH18_BIG_BALL: int = 640;    // type 18, color 2

// S:1103-1106 ANIM(a=1) 后接 VELTIME 2->0.01(20f)、WAIT120、VELTIME 0.01->2.0(120f)
// ANIM 的 position -= 4*velocity 退位移在 fire 的出生坐标里另行保留。
xformdef PHANTOM_AT_BULLET {
    step_speed(0.01fx, 20);
    wait(20);
    wait(120);
    step_speed(2.0fx, 120);
}

// S:27-66 Cir 式的 at：固定环，rank 决定弹数与轮数。
async sub phantom01_at() {
    var n: int = 30;
    var shots: int = 1;
    if global(GVAR_RANK) == RANK_EASY {
        n = 10;
    }
    if global(GVAR_RANK) == RANK_LUNATIC {
        n = 25;
    }
    if global(GVAR_RANK) == RANK_HARD {
        shots = 2;
    }
    if global(GVAR_RANK) == RANK_LUNATIC {
        shots = 3;
    }
    for s in 0..shots {
        var off: angle = (rand(65536) - 32768) as angle; // S:1110 %RANDRAD
        for i in 0..n {
            var a: angle = off + (((i * 65536) / n) as angle); // etAim(0,3)
            // S:1103 ANIM a=1: 出生位置沿速度方向后退 4*2.5
            var px: fx = $self_x - 10fx * cos(a);
            var py: fx = $self_y - 10fx * sin(a);
            _ = fire(TH18_RICE, 6, px, py, 2.5fx, a, PHANTOM_AT_BULLET, none);
        }
        wait(40);    // S:1112
    }
}

// S:1118-1156 atb：240 帧后启动，etAim(0,3)+单弹，每轮重设 ANGLE_PLAYER。
async sub phantom01_atb() {
    var volleys: int = 6;
    var speed: fx = 2.5fx;
    if global(GVAR_RANK) == RANK_EASY {
        volleys = 0;                 // diffI($A, 0, 6, 6, 6)
    }
    if global(GVAR_RANK) >= RANK_HARD {
        speed = 3.0fx;               // S:1126-1134
    }
    for s in 0..volleys {
        var a: angle = aim_player(); // S:1141 %ANGLE_PLAYER
        // S:1137 ANIM a=1: 出生位置沿速度方向后退 4*speed
        var px: fx = $self_x - 4fx * speed * cos(a);
        var py: fx = $self_y - 4fx * speed * sin(a);
        _ = fire(TH18_BIG_BALL, 2, px, py, speed, a, none, none);
        var interval: int = 60;
        if global(GVAR_RANK) == RANK_LUNATIC {
            interval = 50;           // S:1143-1151
        }
        wait(interval);
    }
}

// S:1057-1082 Phantom01：框 28/16，at 出生即跑；240 帧后 atb、ABS 速度插值与
// REL 椭圆(r20, 1deg/frame, beta=ABS_ANGLE=-90deg, s=0)同时生效。
async sub phantom01() {
    set_invuln(65535);               // 无敌练习外壳
    set_hurtbox(14.0fx);             // S:1065 源 28（直径）-> 半径 14
    set_hitbox(8.0fx);               // S:1066 源 16（直径）-> 半径 8
    spawn phantom01_at();            // S:1067
    move_vel(0, -90deg, 0fx, EASE_LINEAR);   // S:1068
    wait(60);                        // S:1069
    wait(180);                       // S:1070
    move_vel(0, -90deg, 0fx, EASE_LINEAR);   // S:1071
    // S:1072 moveVelTime(120,0,-90deg,0.6)：下面手算线性速度斜坡
    spawn phantom01_atb();           // S:1073
    // S:1074 moveEllipseRel(0,1deg,20,0,ABS_ANGLE,0)，beta=-90deg, s=0：
    // 设置当下 x += r*sin(0-beta)*(-sin beta) = +20；此后 REL_x = 20*cos(theta)。
    var cx: fx = $self_x;
    var cy: fx = $self_y;
    var yabs: fx = cy;
    var theta: angle = 0deg;
    var step: int = 0;
    move_vel_xy(0, 20fx, 0fx, EASE_LINEAR);  // 设置当帧的即时 REL 位移
    loop {
        wait(1);
        step = step + 1;
        var spd: fx = 0.6fx;
        if step <= 120 {
            spd = 0.6fx * (step as fx) / 120fx;   // EASE_LINEAR 0->0.6
        }
        yabs = yabs - spd;                       // S:1071-1072 的 ABS 层
        theta = theta + 1deg;
        var tx: fx = cx + 20fx * cos(theta);     // REL 椭圆当前点
        move_vel_xy(0, tx - $self_x, yabs - $self_y, EASE_LINEAR);
    }
}

